// Inyecta los rosters de basquet masculino (2026-27) al set principal, con stats reales.
Object.entries(BBALL_ROSTERS).forEach(([school, players]) => {
  // Si la universidad ya tiene un roster de otro deporte, el de básquet se guarda como "Universidad::Basketball" (antes lo pisaba).
  const bKey = ROSTERS_LOADED[school] && ROSTERS_LOADED[school].sport !== 'Basketball' ? `${school}::Basketball` : school;
  ROSTERS_LOADED[bKey] = { school, roster: players.map(p => ({
    player_name: p.player_name, position: p.position, class_year: p.class_year,
    country: p.country || 'USA', games_played: 0,
    goals: p.ppg || 0, assists: p.apg || 0,
  })), sport: 'Basketball', statsLoaded: true, division: 'NCAA D1', gender: 'M' };
});

// Básquet masculino NCAA D2 — planteles por conferencia (RealGM, bajados el 7/10/2026; 21 de las 23 conferencias: faltan SIAC,
