(function loadVolleyballD1() {
  const nm = (x) => String(x || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z ]/g, " ").replace(/\s+/g, " ").trim();
  const toPlayer = (r) => ({ player_name: r[0], position: r[1], class_year: "", hometown: "", country: "", games_played: r[2], goals: r[3], assists: r[4], digs: r[5], points: r[6] });
  Object.entries(VB_D1_2026.data).forEach(([school, rows]) => {
    const t = VB_D1_2026.team[school];
    const teamStats = t ? { record: t[0], sets: t[1], hit: t[2], opp: t[3] } : null;
    const existing = ROSTERS_LOADED[school] && ROSTERS_LOADED[school].sport === "Volleyball" ? ROSTERS_LOADED[school] : null;
    if (existing) {
      const byName = new Map(rows.map((r) => [nm(r[0]), r]));
      existing.roster.forEach((p) => { const r = byName.get(nm(p.player_name)); if (r) Object.assign(p, { games_played: r[2], goals: r[3], assists: r[4], digs: r[5], points: r[6] }); });
      existing.statsLoaded = true; existing.statsSeason = VB_STATS_SEASON; existing.teamStats = teamStats; existing.positionsKnown = true;
      return;
    }
    if (ROSTERS_LOADED[`${school}::Volleyball`]) return;
    ROSTERS_LOADED[`${school}::Volleyball`] = { school, sport: "Volleyball", gender: "F", division: "NCAA D1", statsLoaded: true, statsSeason: VB_STATS_SEASON, partial: true, positionsKnown: true, teamStats, roster: rows.map(toPlayer) };
  });
})();

