// Devuelve una ficha normalizada sin importar si la fuente es CDS_DATA (rica)
// o ESSLO_DATA (liviana) — para que CollegeProfileCard no tenga que saber de dónde vino.
function getSchoolFicha(school) {
  const rich = CDS_DATA[school];
  if (rich) return { ...rich, source: "cds" };
  const light = ESSLO_DATA[school];
  if (light) {
    const needText = light.need_met
      ? `En promedio cubre ${light.need_met} de la necesidad demostrada. ${light.receiving_aid ? `${light.receiving_aid} de los estudiantes reciben algún tipo de ayuda` : ""}${light.avg_package ? `, paquete promedio de USD ${light.avg_package}/año` : ""}.`
      : "Sin dato de política de ayuda financiera verificado todavía.";
    return {
      ...light,
      majors_offered_ABET: [],
      need_policy: needText,
      verified: true,
      source: "esslo",
    };
  }
  return null;
}

// nunca matchea contra "Chemical Engineering" en el Common Data Set (bug
// real detectado: Delaware con una argentina real en el roster no
// aparecía arriba porque el filtro académico no reconocía el nombre
// en español de la misma carrera que sí ofrece).
const MAJOR_ES_EN = {
  "ingeniería química": "chemical engineering",
  "ingeniería biomédica": "biomedical engineering",
  "ingeniería civil": "civil engineering",
  "ingeniería eléctrica": "electrical engineering",
  "ingeniería mecánica": "mechanical engineering",
  "ingeniería ambiental": "environmental engineering",
  "ciencias de la computación": "computer science",
  "administración de empresas": "business administration",
  "enfermería": "nursing",
  "psicología": "psychology",
  "periodismo": "journalism",
  "educación": "education",
  "ciencias políticas": "political science",
  "salud pública": "public health",
  "biología": "biology",
  "comunicación": "communication",
  "relaciones internacionales": "international affairs",
  "economía": "economics",
  "cocina": "culinary arts",
  "gastronomía": "culinary arts",
  "kinesiología": "kinesiology",
  "ciencias del ejercicio": "exercise science",
  "fisioterapia": "physical therapy",
  "hotelería": "hospitality",
  "arquitectura": "architecture",
  "educación física": "kinesiology",
  "educacion fisica": "kinesiology",
  "profesorado de educación física": "physical education",
  "nutrición": "nutrition",
  "contador": "accounting",
  "contador público": "accounting",
  "contabilidad": "accounting",
  "abogacía": "pre-law",
  "derecho": "pre-law",
  "medicina": "pre-med",
};

function normalizeMajor(m) {
  const lower = m.toLowerCase().trim();
  return MAJOR_ES_EN[lower] || lower;
}

// Carreras por universidad (College Scorecard, campo de estudio, solo licenciatura) para las 1.767 universidades
// del catálogo que tienen roster o perfil NCSA cargado. Cada entrada: [código CIP, ganancia mediana a 4 años tras
// egresar, a 5 años] (null si el dato está protegido por privacidad — muestra chica). CIP_NAMES traduce el código
// al nombre de la carrera (en inglés, como lo reporta el gobierno de EE.UU.). Fuente: collegescorecard.ed.gov,
