// Ramas femeninas de fútbol y básquet: el catálogo original tenía una sola rama por deporte (fútbol y básquet
// solo masculinos). Se agregan los programas femeninos que reporta EADA 2024. Si la universidad ya tiene la
// rama masculina en el catálogo, se copian su conferencia, división y ubicación; si no, se usan las de EADA.
const US_STATE_NAMES = { AL: "Alabama", AK: "Alaska", AZ: "Arizona", AR: "Arkansas", CA: "California", CO: "Colorado", CT: "Connecticut", DE: "Delaware", DC: "District of Columbia", FL: "Florida", GA: "Georgia", HI: "Hawaii", ID: "Idaho", IL: "Illinois", IN: "Indiana", IA: "Iowa", KS: "Kansas", KY: "Kentucky", LA: "Louisiana", ME: "Maine", MD: "Maryland", MA: "Massachusetts", MI: "Michigan", MN: "Minnesota", MS: "Mississippi", MO: "Missouri", MT: "Montana", NE: "Nebraska", NV: "Nevada", NH: "New Hampshire", NJ: "New Jersey", NM: "New Mexico", NY: "New York", NC: "North Carolina", ND: "North Dakota", OH: "Ohio", OK: "Oklahoma", OR: "Oregon", PA: "Pennsylvania", RI: "Rhode Island", SC: "South Carolina", SD: "South Dakota", TN: "Tennessee", TX: "Texas", UT: "Utah", VT: "Vermont", VA: "Virginia", WA: "Washington", WV: "West Virginia", WI: "Wisconsin", WY: "Wyoming", PR: "Puerto Rico" };
const WOMEN_BRANCHES_ADDED = (() => {
  const men = new Map();
  PROGRAMS_ALL_SPORTS.forEach((p) => { if (p.Gender === "M") men.set(`${p.School}|${p.sport}`, p); });
  const have = new Set(PROGRAMS_ALL_SPORTS.map((p) => `${p.School}|${p.sport}|${p.Gender}`));
  const added = { Soccer: 0, Basketball: 0 };
  for (const e of EADA_DATA) {
    for (const [key, sport] of [["soc", "Soccer"], ["bkb", "Basketball"]]) {
      const v = e.sp[key];
      if (!v || !v[1]) continue;
      const school = EADA_DISPLAY_NAME.get(e.u) || e.n;
      if (have.has(`${school}|${sport}|F`)) continue;
      have.add(`${school}|${sport}|F`);
      const m = men.get(`${school}|${sport}`);
      const div = eadaDivision(e.cls);
      PROGRAMS_ALL_SPORTS.push({
        School: school, City: m ? m.City : (e.city || ""), State: m ? m.State : (US_STATE_NAMES[e.st] || e.st),
        Conference: m ? m.Conference : "", Division: m ? m.Division : (div.startsWith("NJCAA") ? "NJCAA" : div),
        sport, Gender: "F", source: "EADA 2024",
      });
      added[sport]++;
    }
  }
  return added;
})();

function checkAcademicFit(university, majorWanted) {
  const cds = CDS_DATA[university];
  const wanted0 = normalizeMajor(majorWanted);
  const isEngineering = /engineering/.test(wanted0); // majors_offered_ABET solo cubre ingenierías acreditadas ABET;
  // para cualquier otra carrera (Economía, Psicología, etc.) esa lista no sirve para decir "no ofrece" — seguimos a Scorecard.
  if (cds && isEngineering) {
    const offered = cds.majors_offered_ABET.some((m) => {
      const mLower = m.toLowerCase();
      return mLower.includes(wanted0) || wanted0.includes(mLower.split(" ")[0]);
    });
    if (offered) return { status: "confirmado_si", cds };
    return { status: "confirmado_no", cds };
  }
  // Sin Common Data Set: probamos con College Scorecard (más universidades, pero solo confirma "sí ofrece" —
  // la ausencia de una carrera acá no significa que no exista, solo que no tuvo graduados recientes reportados,
  // así que nunca devolvemos "confirmado_no" con esta fuente.
  const rows = MAJOR_DATA_BY_SCHOOL[university];
  const ipedsFit = () => {
    const ip = eadaCareerHit(university, majorWanted);
    if (ip && ip.hit) return { status: "confirmado_si", ipeds: ip.hit };
    if (ip && ip.hit === null && ip.related) return { status: "no_verificado", note: `IPEDS no registra "${majorWanted}" con ese nombre, pero tiene una carrera afín: "${ip.related}". Confirmá en su sitio si es la que buscás.`, related: ip.related };
    if (ip && ip.hit === null) return { status: "ipeds_no", note: `IPEDS no registra títulos en "${majorWanted}" en 2024-25 en esta universidad.` };
    return null;
  };
  if (!rows) return ipedsFit() || { status: "no_verificado", note: "No tenemos datos de carreras de esta universidad todavía." };
  const wanted = normalizeMajor(majorWanted);
  const wantedWords = wanted.split(/\s+/).filter((w) => w.length > 2);
  const hit = rows.find((r) => {
    // Comparación por palabra completa (no substring): "biology" no debe matchear "molecular biology" ni al revés
    // con nombres parecidos pero distintos ("biochemistry"). Exige que todas las palabras clave de la carrera
    // buscada aparezcan como palabras completas en el nombre CIP, o viceversa para nombres CIP de una sola palabra.
    const nameWords = (CIP_NAMES[r[0]] || "").toLowerCase().replace(/[,.]/g, " ").split(/\s+/).filter(Boolean);
    const allWanted = wantedWords.length > 0 && wantedWords.every((w) => nameWords.includes(w));
    const singleName = nameWords.length === 1 && wantedWords.includes(nameWords[0]);
    return allWanted || singleName;
  });
  if (!hit) return ipedsFit() || { status: "no_verificado", note: "College Scorecard no muestra graduadas recientes en esa carrera puntual en esta universidad — puede existir igual, no lo pudimos confirmar." };
  return { status: "confirmado_si", scorecard: { name: CIP_NAMES[hit[0]], earn4: hit[1], earn5: hit[2], debt: hit[3] } };
}

